import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
/** Dedicated N05 exact-input immutable intent, one initial physical transfer and registration.
 * Retries recover the original object only. Neither UUIDs nor caller bytes mint these proofs. */
public final class TaskSourceVerifierInvocationObjects {
 private final JdbcTemplate db;private final PermissionSchema json;private final FormalInvocationSchema schema;private final TaskSourceVerifierInvocationSchema exact;private final DependencyManifestSchema manifests;
 public TaskSourceVerifierInvocationObjects(DataSource data,PermissionSchema json,FormalInvocationSchema schema,TaskSourceVerifierInvocationSchema exact,DependencyManifestSchema manifests){db=new JdbcTemplate(data);db.setQueryTimeout(5);this.json=json;this.schema=schema;this.exact=exact;this.manifests=manifests;}
 public Intent prepare(TaskSourceVerifierInvocationContext.Prepared p)throws Exception {
  p.requireUnchanged();var j=p.authority().job();String key=key(p),sha=WireValues.sha256(p.bytes());var old=rows(j.tenant(),key);var runIntents=db.query("SELECT write_key FROM task_source_verifier_exact_intent WHERE tenant_id=? AND run_id=? AND step_id=? LIMIT 2 FOR UPDATE",(r,n)->r.getString(1),j.tenant(),j.run(),j.step());if(runIntents.size()>1||!runIntents.isEmpty()&&!key.equals(runIntents.get(0)))throw new TenantAccessException(ErrorCode.ACTION_STALE);
  if(old.isEmpty()){
   String write=id(),artifact=id();var now=now();String object="runtime/"+j.tenant()+"/"+j.run()+"/"+write+"/"+artifact;
   var intent=json.object().put("schema_version","1.0.0").put("tenant_id",j.tenant()).put("project_id",j.project()).put("run_id",j.run()).put("step_id",j.step()).put("actor_id",j.actor()).put("classification",j.classification()).put("session_id",p.sessionId()).put("request_id",p.requestId()).put("request_sha256",p.requestSha256()).put("write_key",key).put("write_id",write).put("artifact_id",artifact).put("object_key",object).put("payload_sha256",sha).put("size_bytes",Integer.toString(p.bytes().length)).put("schema_ref",TaskSourceVerifierInvocationSchema.EXACT_INPUT_REF).put("payload_schema_sha256",exact.sha256()).put("created_at",now.toString());intent.set("provenance",p.provenance());
   changed(db.update("INSERT INTO task_source_verifier_exact_intent(tenant_id,project_id,run_id,step_id,write_key,write_id,artifact_id,payload,intent_json,intent_sha256,created_by,created_at,classification,schema_version,schema_manifest_sha256) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'1.0.0',?)",j.tenant(),j.project(),j.run(),j.step(),key,write,artifact,new String(p.bytes(),StandardCharsets.UTF_8),schema.canonical(intent),schema.hash(intent),j.actor(),now,j.classification(),exact.sha256()));journal(j,"task.source_verifier.exact.prepared",write,intent,now);
  }
  var result=readIntent(j.tenant(),key);if(!Arrays.equals(result.bytes,p.bytes())||!result.document.required("provenance").equals(p.provenance()))bad();return result;
 }
 public Attempt attempt(TaskSourceVerifierInvocationContext.Prepared p,Intent intent)throws Exception{return attempt(p,intent,true);}
 public void requireAttempt(TaskSourceVerifierInvocationContext.Prepared p,Attempt a)throws Exception {var actual=attempt(p,a.intent,false);if(!actual.intent.document.equals(a.intent.document))bad();}
 private Attempt attempt(TaskSourceVerifierInvocationContext.Prepared p,Intent expected,boolean create)throws Exception {
  var actual=prepare(p);if(!actual.document.equals(expected.document))bad();var j=p.authority().job();String write=actual.writeIntent().writeId();
  var rows=db.queryForList("SELECT * FROM task_source_verifier_exact_attempt WHERE tenant_id=? AND write_id=? LIMIT 2 FOR UPDATE",j.tenant(),write);boolean prior=!rows.isEmpty();
  if(!prior){if(!create)bad();var now=now();changed(db.update("INSERT INTO task_source_verifier_exact_attempt(tenant_id,write_id,intent_sha256,created_by,created_at,project_id,run_id,classification,schema_version,schema_manifest_sha256) VALUES(?,?,?,?,?,?,?,?,'1.0.0',?)",j.tenant(),write,schema.hash(actual.document),j.actor(),now,j.project(),j.run(),j.classification(),exact.sha256()));journal(j,"task.source_verifier.exact.attempted",write,json.object().put("write_id",write).put("intent_sha256",schema.hash(actual.document)),now);}
  verifyAttempt(actual);return new Attempt(actual,prior);
 }
 private void verifyAttempt(Intent intent)throws Exception {
  var n=intent.document;var row=one(db.queryForList("SELECT * FROM task_source_verifier_exact_attempt WHERE tenant_id=? AND write_id=? LIMIT 2",text(n,"tenant_id"),text(n,"write_id")));verifyMetadata(row,n);same(text(n,"actor_id"),str(row,"created_by"));same(schema.hash(n),str(row,"intent_sha256"));verifyJournal(text(n,"tenant_id"),text(n,"project_id"),text(n,"actor_id"),text(n,"classification"),text(n,"run_id"),"task.source_verifier.exact.attempted",text(n,"write_id"),json.object().put("write_id",text(n,"write_id")).put("intent_sha256",schema.hash(n)),time(row,"created_at"));
 }
 public static final class Intent {
  private final JsonNode document;private final byte[] bytes;private Intent(JsonNode document,byte[] bytes){this.document=document.deepCopy();this.bytes=bytes.clone();}
  public S3ObjectWriter.WriteIntent writeIntent(){return new S3ObjectWriter.WriteIntent(text(document,"write_id"),text(document,"object_key"),text(document,"payload_sha256"),text(document,"size_bytes"),"application/json");}
  public String artifactId(){return text(document,"artifact_id");}public byte[] bytes(){return bytes.clone();}
 }
 public static final class Attempt implements RuntimeObjectAttempt {
  private final Intent intent;private final boolean prior;private final java.util.concurrent.atomic.AtomicBoolean claimed=new java.util.concurrent.atomic.AtomicBoolean();private Attempt(Intent intent,boolean prior){this.intent=intent;this.prior=prior;}
  public String tenantId(){return text(intent.document,"tenant_id");}public String actorId(){return text(intent.document,"actor_id");}public String expectedObjectKey(){return "runtime/"+tenantId()+"/"+text(intent.document,"run_id")+"/"+intent.writeIntent().writeId()+"/"+intent.artifactId();}public S3ObjectWriter.WriteIntent writeIntent(){return intent.writeIntent();}public byte[] bytes(){return intent.bytes();}public boolean priorAttempt(){return prior;}public TransferMode claimTransferMode(){return prior||claimed.getAndSet(true)?TransferMode.RECOVER_ONLY:TransferMode.INITIAL_WRITE;}
 }
 public Registered register(TaskSourceVerifierInvocationContext.Prepared p,Attempt attempt,RuntimeObjectTransport.VerifiedTransfer transfer)throws Exception {
  requireAttempt(p,attempt);if(transfer.originalAttempt()!=attempt||!Arrays.equals(p.bytes(),attempt.bytes())||!transfer.rawSha256().equals(WireValues.sha256(p.bytes())))bad();var object=transfer.reference();var intent=attempt.intent;
  if(!intent.writeIntent().objectKey().equals(object.objectKey())||!intent.writeIntent().sha256().equals(object.sha256())||!intent.writeIntent().sizeBytes().equals(object.sizeBytes())||!"application/json".equals(object.mediaType()))bad();var j=p.authority().job();
  var old=db.queryForList("SELECT artifact_id FROM task_source_verifier_exact_registration WHERE tenant_id=? AND write_id=? LIMIT 2 FOR UPDATE",j.tenant(),intent.writeIntent().writeId());
  if(old.isEmpty()){
   var now=now();String access=id();var manifest=new ArtifactRegistryProtocol.DependencyManifest("1.0.0",j.tenant(),j.project(),access,p.contentMembers());String hash=schema.hash(manifest);version(j,access,"DEPENDENCY_ACCESS_SET",hash);version(j,intent.artifactId(),"ARTIFACT",object.sha256());
   var set=meta(j,now,false);set.put("access_set_id",access);set.put("manifest_sha256",hash);set.put("content_sha256",hash);insert("dependency_access_set",set);
   var full=meta(j,now,true);full.put("schema_manifest_sha256",manifests.manifestSha256());full.put("access_set_id",access);full.put("manifest_json",schema.canonical(manifest));full.put("manifest_sha256",hash);full.put("content_sha256",hash);full.put("member_count",p.contentMembers().size());insert("dependency_access_manifest",full);
   for(var member:p.contentMembers()){var m=meta(j,now,false);m.remove("project_id");m.put("access_set_id",access);m.put("upstream_version_id",member.upstreamVersionId());m.put("rights_revision",member.rightsRevision());insert("dependency_access_member",m);}
   var ar=meta(j,now,true);ar.put("artifact_id",intent.artifactId());ar.put("run_id",j.run());ar.put("artifact_kind","TASK_SOURCE_VERIFIER_EXACT_INPUT");ar.put("object_ref",StoredObjectReferences.encode(object));ar.put("object_key",object.objectKey());ar.put("object_version",object.objectVersion());ar.put("sha256",object.sha256());ar.put("size_bytes",object.sizeBytes());ar.put("media_type",object.mediaType());ar.put("dependency_access_set_id",access);ar.put("content_sha256",object.sha256());insert("artifact",ar);
   var binding=meta(j,now,false);binding.put("artifact_id",intent.artifactId());binding.put("resource_kind","TASK");binding.put("resource_id",j.task());binding.put("schema_ref",TaskSourceVerifierInvocationSchema.EXACT_INPUT_REF);binding.put("schema_document_sha256",exact.sha256());binding.put("dependency_access_set_id",access);binding.put("dependency_manifest_sha256",hash);insert("artifact_content_binding",binding);
   for(String root:p.contentRoots())insert("lineage_edge",Map.of("tenant_id",j.tenant(),"consumer_version_id",intent.artifactId(),"upstream_version_id",root,"relation_kind","SOURCE_VERIFIER_CONTEXT","actor_id",j.actor(),"created_at",now));
   var receipt=json.object().put("schema_version","1.0.0").put("kind","TASK_SOURCE_VERIFIER_EXACT_INPUT").put("tenant_id",j.tenant()).put("project_id",j.project()).put("run_id",j.run()).put("task_id",j.task()).put("write_id",intent.writeIntent().writeId()).put("artifact_id",intent.artifactId()).put("intent_sha256",schema.hash(intent.document)).put("created_at",now.toString());receipt.set("object_ref",json.tree(object));receipt.set("dependency_manifest",json.tree(manifest));receipt.set("roots",json.tree(p.contentRoots()));receipt.set("provenance",p.provenance());
   changed(db.update("INSERT INTO task_source_verifier_exact_registration(tenant_id,write_id,artifact_id,receipt_json,receipt_sha256,created_by,created_at,project_id,run_id,classification,schema_version,schema_manifest_sha256) VALUES(?,?,?,?,?,?,?,?,?,?,'1.0.0',?)",j.tenant(),intent.writeIntent().writeId(),intent.artifactId(),schema.canonical(receipt),schema.hash(receipt),j.actor(),now,j.project(),j.run(),j.classification(),exact.sha256()));journal(j,"task.source_verifier.exact.registered",intent.artifactId(),receipt,now);
  }
  var registered=requireStored(j.tenant(),intent.artifactId());if(!registered.receipt.required("provenance").equals(p.provenance())||!registered.reference.equals(object))bad();p.requireUnchanged();return registered;
 }
 public final class Registered {
  private final String tenant,artifact;private final JsonNode receipt;private final byte[] bytes;private final InterfaceProtocol.ObjectRef reference;
  private Registered(String tenant,String artifact,JsonNode receipt,byte[] bytes,InterfaceProtocol.ObjectRef reference){this.tenant=tenant;this.artifact=artifact;this.receipt=receipt.deepCopy();this.bytes=bytes.clone();this.reference=reference;}
  public void requireUnchanged()throws Exception {var fresh=requireStored(tenant,artifact);if(!receipt.equals(fresh.receipt)||!Arrays.equals(bytes,fresh.bytes))bad();}
  public String artifactId(){return artifact;}public String accessSetId(){return text(receipt.required("dependency_manifest"),"access_set_id");}public JsonNode receipt(){return receipt.deepCopy();}public byte[] bytes(){return bytes.clone();}public InterfaceProtocol.ObjectRef reference(){return reference;}
 }
 Registered requireStored(String tenant,String artifact)throws Exception {
  if(!org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()||!TenantScope.requireCurrent().tenantId().equals(tenant))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
  var row=one(db.queryForList("SELECT * FROM task_source_verifier_exact_registration WHERE tenant_id=? AND artifact_id=? LIMIT 2",tenant,artifact));var receipt=schema.parse(str(row,"receipt_json"));same(schema.hash(receipt),str(row,"receipt_sha256"));same(schema.canonical(receipt),str(row,"receipt_json"));same(artifact,text(receipt,"artifact_id"));same(tenant,text(receipt,"tenant_id"));
  var intentRow=one(db.queryForList("SELECT * FROM task_source_verifier_exact_intent WHERE tenant_id=? AND write_id=? LIMIT 2",tenant,text(receipt,"write_id")));var intent=readIntent(tenant,str(intentRow,"write_key"));verifyAttempt(intent);verifyMetadata(row,intent.document);same(text(receipt,"write_id"),str(row,"write_id"));same(schema.hash(intent.document),text(receipt,"intent_sha256"));same(intent.document.required("provenance"),receipt.required("provenance"));same(intent.artifactId(),artifact);for(String k:List.of("tenant_id","project_id","run_id","write_id"))same(text(intent.document,k),text(receipt,k));same("TASK_SOURCE_VERIFIER_EXACT_INPUT",text(receipt,"kind"));same("1.0.0",text(receipt,"schema_version"));
  var parser=new com.fasterxml.jackson.databind.ObjectMapper().setPropertyNamingStrategy(com.fasterxml.jackson.databind.PropertyNamingStrategies.SNAKE_CASE);var ref=parser.treeToValue(receipt.required("object_ref"),InterfaceProtocol.ObjectRef.class);same(ref.sha256(),WireValues.sha256(intent.bytes));same(ref.objectKey(),intent.writeIntent().objectKey());same(ref.sizeBytes(),Integer.toString(intent.bytes.length));same("application/json",ref.mediaType());if(ref.objectVersion()==null||ref.objectVersion().isBlank())bad();
  var ar=one(db.queryForList("SELECT * FROM artifact WHERE tenant_id=? AND artifact_id=? LIMIT 2",tenant,artifact));same(ref,StoredObjectReferences.decode(str(ar,"object_ref"),ref));for(var pin:Map.of("project_id",text(receipt,"project_id"),"run_id",text(receipt,"run_id"),"artifact_kind","TASK_SOURCE_VERIFIER_EXACT_INPUT","sha256",ref.sha256(),"content_sha256",ref.sha256(),"object_key",ref.objectKey(),"object_version",ref.objectVersion(),"size_bytes",ref.sizeBytes(),"media_type",ref.mediaType()).entrySet())same(pin.getValue(),str(ar,pin.getKey()));
  String access=text(receipt.required("dependency_manifest"),"access_set_id"),hash=schema.hash(receipt.required("dependency_manifest"));same(access,str(ar,"dependency_access_set_id"));
  var binding=one(db.queryForList("SELECT * FROM artifact_content_binding WHERE tenant_id=? AND artifact_id=? LIMIT 2",tenant,artifact));for(var pin:Map.of("project_id",text(receipt,"project_id"),"resource_kind","TASK","resource_id",text(receipt,"task_id"),"schema_ref",TaskSourceVerifierInvocationSchema.EXACT_INPUT_REF,"schema_document_sha256",exact.sha256(),"dependency_access_set_id",access,"dependency_manifest_sha256",hash).entrySet())same(pin.getValue(),str(binding,pin.getKey()));
  var manifest=one(db.queryForList("SELECT * FROM dependency_access_manifest WHERE tenant_id=? AND access_set_id=? LIMIT 2",tenant,access));same(receipt.required("dependency_manifest"),schema.parse(str(manifest,"manifest_json")));same(hash,str(manifest,"content_sha256"));same(hash,str(manifest,"manifest_sha256"));same(manifests.manifestSha256(),str(manifest,"schema_manifest_sha256"));
  var set=one(db.queryForList("SELECT * FROM dependency_access_set WHERE tenant_id=? AND access_set_id=? LIMIT 2",tenant,access));same(hash,str(set,"content_sha256"));same(hash,str(set,"manifest_sha256"));
  var actual=db.queryForList("SELECT upstream_version_id,rights_revision FROM dependency_access_member WHERE tenant_id=? AND access_set_id=? ORDER BY upstream_version_id LIMIT 10001",tenant,access);var members=receipt.required("dependency_manifest").required("members");if(actual.size()!=members.size())bad();for(int i=0;i<actual.size();i++){same(text(members.get(i),"upstream_version_id"),str(actual.get(i),"upstream_version_id"));same(text(members.get(i),"rights_revision"),str(actual.get(i),"rights_revision"));}
  var roots=db.query("SELECT upstream_version_id FROM lineage_edge WHERE tenant_id=? AND consumer_version_id=? AND relation_kind='SOURCE_VERIFIER_CONTEXT' ORDER BY upstream_version_id LIMIT 10001",(r,n)->r.getString(1),tenant,artifact);same(json.tree(roots),receipt.required("roots"));if(one(db.query("SELECT COUNT(*) FROM lineage_edge WHERE tenant_id=? AND consumer_version_id=?",(r,n)->r.getInt(1),tenant,artifact))!=roots.size())bad();
  for(var pin:List.of(Map.entry(artifact,ref.sha256()),Map.entry(access,hash))){var version=one(db.queryForList("SELECT * FROM version_registry WHERE tenant_id=? AND version_id=? LIMIT 2",tenant,pin.getKey()));same(pin.getValue(),str(version,"content_sha256"));same(text(receipt,"project_id"),str(version,"owner_project_id"));same(pin.getKey().equals(artifact)?"ARTIFACT":"DEPENDENCY_ACCESS_SET",str(version,"entity_kind"));}
  var at=time(row,"created_at");same(at.toString(),text(receipt,"created_at"));verifyJournal(tenant,text(receipt,"project_id"),text(intent.document,"actor_id"),text(intent.document,"classification"),text(receipt,"run_id"),"task.source_verifier.exact.registered",artifact,receipt,at);exact.readExactInput(intent.bytes);return new Registered(tenant,artifact,receipt,intent.bytes,ref);
 }
 private Intent readIntent(String tenant,String key)throws Exception {
  var row=one(rows(tenant,key));var doc=schema.parse(str(row,"intent_json"));same(schema.hash(doc),str(row,"intent_sha256"));same(schema.canonical(doc),str(row,"intent_json"));var payload=exact.readExactInput(str(row,"payload").getBytes(StandardCharsets.UTF_8));byte[] bytes=ContentReadAuthorization.canonicalBytes(payload);same(new String(bytes,StandardCharsets.UTF_8),str(row,"payload"));same(WireValues.sha256(bytes),text(doc,"payload_sha256"));same(Integer.toString(bytes.length),text(doc,"size_bytes"));same(exact.sha256(),text(doc,"payload_schema_sha256"));same(TaskSourceVerifierInvocationSchema.EXACT_INPUT_REF,text(doc,"schema_ref"));
  verifyMetadata(row,doc);for(String k:List.of("tenant_id","project_id","run_id","step_id","write_key","write_id","artifact_id","classification"))same(str(row,k),text(doc,k));same(str(row,"created_by"),text(doc,"actor_id"));same(time(row,"created_at").toString(),text(doc,"created_at"));
  if(!text(doc,"object_key").equals("runtime/"+tenant+"/"+text(doc,"run_id")+"/"+text(doc,"write_id")+"/"+text(doc,"artifact_id")))bad();
  verifyJournal(tenant,text(doc,"project_id"),text(doc,"actor_id"),text(doc,"classification"),text(doc,"run_id"),"task.source_verifier.exact.prepared",text(doc,"write_id"),doc,time(row,"created_at"));return new Intent(doc,bytes);
 }
 private void verifyMetadata(Map<String,Object> row,JsonNode doc){same("1.0.0",str(row,"schema_version"));same(exact.sha256(),str(row,"schema_manifest_sha256"));for(String k:List.of("tenant_id","project_id","run_id","classification"))same(text(doc,k),str(row,k));same(text(doc,"actor_id"),str(row,"created_by"));}
 private String key(TaskSourceVerifierInvocationContext.Prepared p)throws Exception {return WireValues.sha256(("TASK_SOURCE_VERIFIER_EXACT_INPUT/"+p.authority().job().run()+"/"+p.authority().leaseGeneration()+"/"+p.sessionId()+"/"+p.requestId()+"/"+p.requestSha256()).getBytes(StandardCharsets.US_ASCII));}
 private List<Map<String,Object>> rows(String tenant,String key){return db.queryForList("SELECT * FROM task_source_verifier_exact_intent WHERE tenant_id=? AND write_key=? LIMIT 2 FOR UPDATE",tenant,key);}
 private void journal(TaskSourceVerifierRuntimeAuthority.Job j,String action,String target,JsonNode document,LocalDateTime at)throws Exception {changed(db.update("INSERT INTO audit_event(tenant_id,project_id,audit_id,subject_id,action,resource_ref,result,request_id,trace_id,schema_version,schema_manifest_sha256,created_by,created_at,classification) VALUES(?,?,?,?,?,?,'SUCCESS',?,?,'1.0.0',?,?,?,?)",j.tenant(),j.project(),id(),j.actor(),action,schema.canonical(document),target,j.run(),exact.sha256(),j.actor(),at,j.classification()));changed(db.update("INSERT INTO outbox_event(tenant_id,event_id,aggregate_id,aggregate_revision,event_type,payload,occurred_at) VALUES(?,?,?,1,?,?,?)",j.tenant(),id(),target,action,schema.canonical(document),at));}
 private void verifyJournal(String tenant,String project,String actor,String classification,String run,String action,String target,JsonNode expected,LocalDateTime at)throws Exception {same(expected,schema.parse(one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND subject_id=? AND created_by=? AND action=? AND request_id=? AND trace_id=? AND result='SUCCESS' AND reason_code IS NULL AND schema_version='1.0.0' AND schema_manifest_sha256=? AND classification=? AND created_at=? LIMIT 2",(r,n)->r.getString(1),tenant,project,actor,actor,action,target,run,exact.sha256(),classification,at))));same(expected,schema.parse(one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND aggregate_id=? AND aggregate_revision=1 AND event_type=? AND occurred_at=? LIMIT 2",(r,n)->r.getString(1),tenant,target,action,at))));}
 private Map<String,Object> meta(TaskSourceVerifierRuntimeAuthority.Job j,LocalDateTime at,boolean version){var m=new LinkedHashMap<String,Object>();m.put("tenant_id",j.tenant());m.put("project_id",j.project());m.put("created_by",j.actor());m.put("created_at",at);m.put("classification",j.classification());if(version){m.put("schema_version","1.0.0");m.put("schema_manifest_sha256",exact.sha256());}return m;}
 private void version(TaskSourceVerifierRuntimeAuthority.Job j,String id,String kind,String hash){insert("version_registry",Map.of("tenant_id",j.tenant(),"version_id",id,"owner_project_id",j.project(),"entity_kind",kind,"content_sha256",hash));}
 private void insert(String table,Map<String,Object> values){var keys=new ArrayList<>(values.keySet());changed(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(values::get).toArray()));}
 private LocalDateTime now(){return one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));}private static LocalDateTime time(Map<String,Object> row,String key){var v=row.get(key);if(v instanceof LocalDateTime t)return t;if(v instanceof java.sql.Timestamp t)return t.toLocalDateTime();bad();return null;}
 private static String id(){return UUID.randomUUID().toString();}private static String text(JsonNode n,String k){if(!n.required(k).isTextual())bad();return n.required(k).textValue();}private static String str(Map<String,Object> n,String k){if(n.get(k)==null)bad();return n.get(k).toString();}private static void same(Object a,Object b){if(!Objects.equals(a,b))bad();}private static <T>T one(List<T> rows){if(rows.size()!=1)bad();return rows.get(0);}private static void changed(int n){if(n!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
